    const res = await app.handle("POST", "/orders", placeOrderBody());

    assert.equal(res.status, 201);
    assert.deepEqual(res.body, {
      id: "ord-1",
      status: "placed",
      placedAt: FIXED_NOW,
      currency: "USD",
